function addDays(d, n){ return new Date(d.getTime() + n*86400000); }
function ovulation(lmp, cycleLen){ return addDays(lmp, cycleLen-14); } // 黄体期固定 14 天
function fertileWindow(lmp, cycleLen){
  var ov=ovulation(lmp, cycleLen);
  return { start: addDays(ov,-5), end: addDays(ov,1) };
}
var EXPORTS={addDays:addDays, ovulation:ovulation, fertileWindow:fertileWindow};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.OvulationForgePure = EXPORTS; }
